#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

bool tryOne(vector<int>& p, int pos, int target, vector<pair<int,int>>& ops) {
    int n = p.size();
    // Case 1: pos < x, x+y = n - target + pos
    int s1 = n - target + pos;
    for (int x = pos+1; x < n && x < s1; x++) {
        int y = s1 - x;
        if (y >= 1 && x+y < n && pos < x && n-y > pos) { // also n-y > x is middle non-negative: n-y >= x
            if (n - y >= x) { ops.push_back({x,y}); apply(p,x,y); return true; }
        }
    }
    // Case 2: x <= pos < n-y, x - y = pos - target
    int d = pos - target;
    for (int y = 1; y < n; y++) {
        int x = d + y;
        if (x >= 1 && x+y < n && x <= pos && n-y > pos) {
            ops.push_back({x,y}); apply(p,x,y); return true;
        }
    }
    // Case 3: pos >= n-y, y = target - pos + n
    { int y = target - pos + n;
      if (y >= 1 && y <= n - pos) {
        for (int x = 1; x + y < n; x++) {
            if (n - y <= pos) { ops.push_back({x,y}); apply(p,x,y); return true; }
        }
      }
    }
    return false;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    for(int k=0;k<n;k++){
        int pos=-1;
        for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
        if(pos==k) continue;
        if(!tryOne(p,pos,k,ops)){
            // Move to position n-1 first, then to k
            if(pos < n-1) { ops.push_back({1, n-1-pos}); apply(p,1,n-1-pos); pos=n-1-pos<=0?pos:0; for(int i=0;i<n;i++) if(p[i]==k+1){pos=i;break;} }
            if(pos!=k) tryOne(p,pos,k,ops);
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
